import React from 'react';
import ReactDOM from 'react-dom';
import { CascaderSelect } from '@alifd/next';
import produce from 'immer';

// Example data
const rawData = [
  {
    value: '1',
    label: 'Option 1',
    children: [
      { value: '1-1', label: 'Option 1-1' },
      { value: '1-2', label: 'Option 1-2' }
    ]
  },
  {
    value: '2',
    label: 'Option 2',
    children: [
      { value: '2-1', label: 'Option 2-1' },
      { value: '2-2', label: 'Option 2-2' }
    ]
  }
];

// Use immer to create a frozen (immutable) data structure
const immutableData = produce(rawData, draft => {});

// Or, you can use Object.freeze for a quick test:
// const immutableData = Object.freeze(rawData);

function App() {
  return (
    <CascaderSelect dataSource={immutableData} />
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
